import '../utils/json.dart';

/// A single Coolify one-click service type, from the official
/// `templates/service-templates.json` catalogue.
class ServiceTemplate {
  const ServiceTemplate(this.type, this.slogan, this.logoUrl);

  final String type;
  final String slogan;

  /// Absolute URL of the catalogue logo, or null when upstream has none.
  /// Loaded lazily on demand — never bundled into the APK.
  final String? logoUrl;

  factory ServiceTemplate.fromJson(Map<String, dynamic> m) =>
      ServiceTemplate(jsonStr(m, 'type') ?? '', jsonStr(m, 'slogan') ?? '',
          jsonStr(m, 'logo'));

